460	int main(void)
461	{
462	    struct bt_gatt_attr *vnd_ind_attr;
463	    char str[BT_UUID_STR_LEN];
464	    int err;
465	
466	    err = bt_enable(NULL);
467	    if (err)
468	    {
469	        printk("Bluetooth init failed (err %d)\n", err);
470	        return 0;
471	    }
472	
473	    bt_ready();
474	    bt_cts_init(&cts_cb);
475	    bt_hrs_cb_register(&hrs_cb);
476	
477	    bt_gatt_cb_register(&gatt_callbacks);
478	    bt_conn_auth_cb_register(&auth_cb_display);
479	
480	    vnd_ind_attr = bt_gatt_find_by_uuid(vnd_svc.attrs, vnd_svc.attr_count,
481	                                        &vnd_enc_uuid.uuid);
482	    bt_uuid_to_str(&vnd_enc_uuid.uuid, str, sizeof(str));
483	    printk("Indicate VND attr %p (UUID %s)\n", vnd_ind_attr, str);
484	
485	    k_work_init_delayable(&deferred_work_bt_ready, deferred_work);
486	
487	    /* Implement notification. At the moment there is no suitable way
488	     * of starting delayed work so we do it here
489	     */
490	    while (1)
491	    {
492	        k_sleep(K_SECONDS(1));
493	
494	        /* Current time update notification example
495	         * For testing purposes, we send a manual update notification every second.
496	         * In production `bt_cts_send_notification` should only be used when time is changed
497	         */
498	        if (cts_notification_enabled)
499	        {
500	            bt_cts_send_notification(BT_CTS_UPDATE_REASON_MANUAL);
501	        }
502	        /* Heartrate measurements simulation */
503	        hrs_notify();
504	
505	        /* Battery level simulation */
506	        bas_notify();
507	
508	        /* Vendor indication simulation */
509	        if (simulate_vnd && vnd_ind_attr)
510	        {
511	            if (indicating)
512	            {
513	                continue;
514	            }
515	
516	            ind_params.attr = vnd_ind_attr;
517	            ind_params.func = indicate_cb;
518	            ind_params.destroy = indicate_destroy;
519	            ind_params.data = &indicating;
520	            ind_params.len = sizeof(indicating);
521	
522	            if (bt_gatt_indicate(NULL, &ind_params) == 0)
523	            {
524	                indicating = 1U;
525	            }
526	        }
527	    }
528	    return 0;
529	}
