613	static int32_t sf32lb58_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
614	{
615	  syslog(LOG_INFO, "sf32lb58 rx_ind: handle=%ld size=%lu\n",
616	         (long)handle, (unsigned long)size);
617	  struct sf32lb58_bt_env_s *env = &g_sf32lb58_bt_env;
618	  irqstate_t flags;
619	  bool queue_work;
620	
621	  if (handle != env->ipc_port)
622	    {
623	      return -EINVAL;
624	    }
625	
626	  if (!env->queue_open)
627	    {
628	      return OK;
629	    }
630	
631	  flags = enter_critical_section();
632	  env->rx_work_pending = true;
633	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
634	  if (queue_work)
635	    {
636	      env->rx_worker_running = true;
637	    }
638	  leave_critical_section(flags);
639	
640	  syslog(LOG_INFO, "sf32lb58 rx_ind: queue_work=%d rx_worker_running=%d "
641	         "work_available=%d\n",
642	         queue_work, env->rx_worker_running,
643	         work_available(&env->rx_work));
644	
645	  if (queue_work)
646	    {
647	      int ret;
648	
649	      ret = work_queue(HPWORK, &env->rx_work, sf32lb58_bt_rx_worker,
650	                       env, 0);
651	      syslog(LOG_INFO, "sf32lb58 rx_ind: work_queue returned %d\n", ret);
652	      if (ret < 0)
653	        {
654	          flags = enter_critical_section();
655	          env->rx_worker_running = false;
656	          leave_critical_section(flags);
657	
658	          syslog(LOG_ERR, "sf32lb58 bt queue rx work failed: %d\n", ret);
659	          return ret;
660	        }
661	    }
662	
663	  return OK;
664	}
