770	int sf32lb58_bt_controller_enable(void)
771	{
772	  int ret;
773	
774	  if (g_sf32lb58_bt_status == SF32LB58_BT_STATUS_ENABLED)
775	    {
776	      return OK;
777	    }
778	
779	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_INITED)
780	    {
781	      return -EPERM;
782	    }
783	
784	  syslog(LOG_INFO, "sf32lb58 bt: preparing NVDS at 0x%08x size %d\n",
785	         (unsigned int)SF32LB58_BT_NVDS_BUF_START,
786	         (int)SF32LB58_BT_NVDS_BUF_SIZE);
787	  sf32lb58_bt_prepare_stack_nvds();
788	  HAL_LCPU_ASSERT_INFO_clear();
789	
790	  /* Wake the LCPU first so the LPSYS bus bridge is powered.
791	   * This must happen BEFORE lcpu_power_on() because the IPC mailbox
792	   * CxIER register is on the LPSYS APB bus and only writable when
793	   * the bus bridge is active.  lcpu_power_on() will reset+halt the
794	   * LCPU and reconfigure it, so this early wake is just for the bus
795	   * bridge power domain.
796	   */
797	
798	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
799	  g_sf32lb58_bt_env.wake_held = true;
800	
801	  syslog(LOG_INFO, "sf32lb58 bt: powering on LCPU\n");
802	  ret = lcpu_power_on();
803	  if (ret != 0)
804	    {
805	      syslog(LOG_ERR, "sf32lb58 bt: lcpu_power_on failed: %d\n", ret);
806	      return -EIO;
807	    }
808	
809	  syslog(LOG_INFO, "sf32lb58 bt: LCPU powered on, opening IPC\n");

808	
809	  syslog(LOG_INFO, "sf32lb58 bt: LCPU powered on, opening IPC\n");
810	
811	  /* lcpu_power_on() keeps the bus bridge active (no cancel inside).
812	   * Open the IPC queue while the bridge is powered, then cancel.
813	   */
814	
815	  g_sf32lb58_bt_env.wake_held = true;
816	
817	  syslog(LOG_INFO, "sf32lb58 bt: calling ipc_queue_open\n");
818	  ret = ipc_queue_open(g_sf32lb58_bt_env.ipc_port);
819	  syslog(LOG_INFO, "sf32lb58 bt: ipc_queue_open returned %d\n", ret);
820	
821	  /* Check if NVIC interrupt for mailbox is enabled */
822	  {
823	    uint32_t iser0 = NVIC->ISER[0];
824	    uint32_t iser1 = NVIC->ISER[1];
825	    syslog(LOG_INFO, "sf32lb58 bt: NVIC ISER0=%08lx ISER1=%08lx\n",
826	           (unsigned long)iser0, (unsigned long)iser1);
827	  }
828	  if (ret < 0)
829	    {
830	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
831	      g_sf32lb58_bt_env.wake_held = false;
832	      return ret;
833	    }
834	
835	  syslog(LOG_INFO, "sf32lb58 bt: flushing TX ring, then waiting RX ring\n");
836	  up_clean_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
837	                  (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
838	                  SF32LB58_BT_TX_BUF_SIZE);
839	  __DSB();
840	
841	  {
842	    struct circular_buf *rx_ring =
843	        (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
844	
845	    ret = sf32lb58_bt_wait_rx_ring_ready();
846	    if (ret < 0)
847	      {
848	        syslog(LOG_ERR, "sf32lb58 rx ring not ready: %d\n", ret);
849	        ipc_queue_close(g_sf32lb58_bt_env.ipc_port);
850	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
851	        g_sf32lb58_bt_env.wake_held = false;
852	        return ret;
853	      }
854	
855	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
856	    g_sf32lb58_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
857	
858	    up_clean_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
859	                    (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
860	                    sizeof(*rx_ring));
861	    __DSB();
862	  }
863	
864	  g_sf32lb58_bt_env.queue_open = true;
865	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_ENABLED;
866	
867	  return OK;
868	}
