870	int sf32lb58_bt_controller_disable(void)
871	{
872	  int ret = OK;
873	  int tmpret;
874	  bool queue_open;
875	
876	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_ENABLED)
877	    {
878	      return -EPERM;
879	    }
880	
881	  queue_open = g_sf32lb58_bt_env.queue_open;
882	  g_sf32lb58_bt_env.queue_open = false;
883	  g_sf32lb58_bt_env.rx_work_pending = false;
884	  g_sf32lb58_bt_env.rx_worker_running = false;
885	  if (!work_available(&g_sf32lb58_bt_env.rx_work))
886	    {
887	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb58_bt_env.rx_work);
888	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
889	        {
890	          ret = tmpret;
891	        }
892	    }
893	
894	  if (queue_open)
895	    {
896	      tmpret = ipc_queue_close(g_sf32lb58_bt_env.ipc_port);
897	      if (tmpret < 0 && ret == OK)
898	        {
899	          ret = tmpret;
900	        }
901	    }
902	
903	  if (g_sf32lb58_bt_env.wake_held)
904	    {
905	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
906	      g_sf32lb58_bt_env.wake_held = false;
907	    }
908	
909	  tmpret = lcpu_power_off();
910	  if (tmpret != 0 && ret == OK)
911	    {
912	      ret = -EIO;
913	    }
914	
915	  g_sf32lb58_bt_env.notify_host = NULL;
916	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_INITED;
917	  return ret;
918	}
