33	#define IPC_QUEUE_HANDLE_2_OFFSET(handle)  ((handle) - IPC_QUEUE_HANDLE_OFFSET)
34	#define IPC_QUEUE_OFFSET_2_HANDLE(offset)  ((offset) + IPC_QUEUE_HANDLE_OFFSET)
