45	static bool is_valid_handle(ipc_queue_handle_t handle)
46	{
47	    bool valid = false;
48	    int32_t offset;
49	
50	    if (!ipc_ctx.init)
51	    {
52	        return valid;
53	    }
54	
55	    if ((handle < IPC_QUEUE_HANDLE_OFFSET)
56	            || ((handle - IPC_QUEUE_HANDLE_OFFSET) >= IPC_LOGICAL_QUEUE_NUM))
57	    {
58	        return valid;
59	    }
60	
61	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
62	    if (IPC_INVALID_QUEUE_ID == ipc_ctx.queues[offset].cfg.qid)
63	    {
64	        return valid;
65	    }
66	
67	    valid = true;
68	
69	    return valid;
70	}
