72	__ROM_USED ipc_queue_handle_t ipc_queue_init(ipc_queue_cfg_t *q_cfg)
73	{
74	    uint32_t i;
75	    ipc_queue_handle_t handle = IPC_QUEUE_INVALID_HANDLE;
76	    int32_t offset;
77	    ipc_queue_t *ipc_queue;
78	    uint32_t mask;
79	
80	    if (NULL == q_cfg)
81	    {
82	        return handle;
83	    }
84	
85	    mask = os_interrupt_disable();
86	
87	    /* initialize ipc queues */
88	    if (!ipc_ctx.init)
89	    {
90	        for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
91	        {
92	            ipc_ctx.queues[i].cfg.qid = IPC_INVALID_QUEUE_ID;
93	            ipc_ctx.queues[i].active = false;
94	        }
95	        ipc_ctx.init = true;
96	    }
97	
98	    ipc_queue = &ipc_ctx.queues[0];
99	    offset = -1;
100	    for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
101	    {
102	        if (q_cfg->qid == ipc_queue->cfg.qid)
103	        {
104	            /* qid already present */
105	            handle = IPC_QUEUE_INVALID_HANDLE;
106	            break;
107	        }
108	        if ((IPC_QUEUE_INVALID_HANDLE == handle)
109	                && (IPC_INVALID_QUEUE_ID == ipc_queue->cfg.qid))
110	        {
111	            /* first vacant found */
112	            offset = i;
113	            handle = IPC_QUEUE_OFFSET_2_HANDLE(offset);
114	        }
115	        ipc_queue++;
116	    }
117	
118	    if ((i >= IPC_LOGICAL_QUEUE_NUM) && (offset >= 0))
119	    {

119	    if ((i >= IPC_LOGICAL_QUEUE_NUM) && (offset >= 0))
120	    {
121	        /* new qid and vacant found */
122	        memcpy(&ipc_ctx.queues[offset].cfg, q_cfg, sizeof(*q_cfg));
123	        ipc_ctx.queues[offset].data_len = 0;
124	        ipc_ctx.queues[offset].active = false;
125	    }
126	
127	    os_interrupt_enable(mask);
128	
129	    return handle;
130	}
