static int32_t sf32lb58_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
{
  struct sf32lb58_bt_env_s *env = &g_sf32lb58_bt_env;

  syslog(LOG_INFO, "sf32lb58 rx_ind: handle=%ld size=%lu\n",
         (long)handle, (unsigned long)size);

  if (handle != env->ipc_port)
    {
      return -EINVAL;
    }

  if (!env->queue_open)
    {
      return OK;
    }

  /* Process rx data directly in ISR context.
   * HPWORK was not dispatching the work item for unknown reasons.
   * This is safe because the rx processing is fast (read ring buffer +
   * call notify_host callback).
   */

  up_invalidate_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
                       (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
                       SF32LB58_BT_RX_BUF_SIZE);

  {
    struct circular_buf *rx_ring =
        (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
    uint32_t wr_ptr = rx_ring->write_idx_mirror;
    uint32_t rd_ptr = env->rx_read_idx_mirror;
    uint32_t buf_size = rx_ring->buffer_size;
    uint32_t data_len;

    if (wr_ptr >= rd_ptr)
      {
        data_len = wr_ptr - rd_ptr;
      }
    else
      {
