static FAR void *sf32lb58_bt_rx_thread(FAR void *arg)
{
  struct sf32lb58_bt_env_s *env = arg;

  syslog(LOG_INFO, "sf32lb58 rx_thread: started\n");

  for (;;)
    {
      /* Wait for rx_ind to post the semaphore */

      nxsem_wait(&env->rx_sem);

      if (!env->queue_open)
        {
          break;
        }

      /* Read all available data from the IPC queue */

      for (;;)
        {
          size_t got = ipc_queue_read(env->ipc_port, env->data_buf,
                                      sizeof(env->data_buf));
          if (got == 0)
            {
              break;
            }

          env->rx_count++;

          if (env->notify_host != NULL)
            {
              int ret = env->notify_host(env->data_buf, got);
              if (ret < 0)
                {
                  syslog(LOG_ERR, "sf32lb58 bt rx callback: %d\n", ret);
                }
            }
        }
    }

  syslog(LOG_INFO, "sf32lb58 rx_thread: exiting\n");
  return NULL;
}

