{
  int ret;

  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_IDLE)
    {
      return OK;
    }

  memset(&g_sf32lb58_bt_env, 0, sizeof(g_sf32lb58_bt_env));
  g_sf32lb58_bt_env.ipc_port = IPC_QUEUE_INVALID_HANDLE;

  nxsem_init(&g_sf32lb58_bt_env.rx_sem, 0, 0);

  ret = sf32lb58_bt_mailbox_init();
  if (ret < 0)
    {
      nxsem_destroy(&g_sf32lb58_bt_env.rx_sem);
      return ret;
    }

  /* Create the dedicated rx processing thread */

  {
    struct sched_param param;
    pthread_attr_t attr;

    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, 4096);
    param.sched_priority = 200;
    pthread_attr_setschedparam(&attr, &param);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

    ret = pthread_create(&g_sf32lb58_bt_env.rx_thread, &attr,
                         sf32lb58_bt_rx_thread, &g_sf32lb58_bt_env);
    if (ret != 0)
      {
        syslog(LOG_ERR, "sf32lb58 bt: rx thread create failed: %d\n", ret);
        nxsem_destroy(&g_sf32lb58_bt_env.rx_sem);
        return -ret;
      }

    pthread_attr_destroy(&attr);
  }

  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_INITED;
  return OK;
}

